"""The NASA TMR NACA 0012 validation case (docs/validation/naca0012/SETUP.md): the airfoil generated by code and
the app project set up for it. No Qt.

Geometry: the TMR revised NACA 0012 (https://tmbwg.github.io/turbmodels/naca0012_val.html, "Description"): the
exact NACA 0012 thickness built between x = 0 and 1.008930411365 (where it closes) and scaled to chord 1,
y = +- 0.594689181 [0.298222773 sqrt(x) - 0.127125232 x - 0.357907906 x^2 + 0.291984971 x^3
- 0.105174606 x^4], sharp trailing edge at x = 1, maximum thickness about 11.894 %.
"""

import math
from pathlib import Path

import numpy as np

TMR_COEFFS = (0.298222773, -0.127125232, -0.357907906, 0.291984971, -0.105174606)
TMR_FACTOR = 0.594689181


def tmr_half_thickness(x: np.ndarray) -> np.ndarray:
    """The TMR NACA 0012 half thickness at x (chord 1); 0 at x = 0 and (to 1e-9) at x = 1."""
    a0, a1, a2, a3, a4 = TMR_COEFFS
    return TMR_FACTOR * (a0 * np.sqrt(x) + a1 * x + a2 * x ** 2 + a3 * x ** 3 + a4 * x ** 4)


def selig_text(points_per_surface: int = 401) -> str:
    """The airfoil as a Selig coordinate file: cosine-spaced x (clustered at both edges), from the trailing
    edge over the upper surface to the leading edge and back along the lower surface; the trailing edge
    point is exactly (1, 0)."""
    beta = np.linspace(0.0, math.pi, points_per_surface)
    x = 0.5 * (1.0 - np.cos(beta))
    t = tmr_half_thickness(x)
    t[0], t[-1] = 0.0, 0.0
    rows = [f"{xi:.10f} {ti:.10f}" for xi, ti in zip(x[::-1], t[::-1])]
    rows += [f"{xi:.10f} {-ti:.10f}" for xi, ti in zip(x[1:], t[1:])]
    return "NACA 0012 (NASA TMR, closed trailing edge, chord 1)\n" + "\n".join(rows) + "\n"


def write_dat(path: Path, points_per_surface: int = 401) -> Path:
    Path(path).write_text(selig_text(points_per_surface), encoding="utf-8")
    return Path(path)


# -- the validation set-up (docs/validation/naca0012/SETUP.md) --------------------------------------------------

# NASA TMR, "NACA 0012 Validation, SST" (https://tmbwg.github.io/turbmodels/naca0012_val_sst.html): CFL3D, FUN3D
# and NTS on the 897 x 257 grid (the finest listed there), SSTm; CL at 0 deg "approx 0".
TMR_SST = {
    "CFL3D": {0.0: (0.0, 0.00809), 10.0: (1.0778, 0.01236), 15.0: (1.5068, 0.02219)},
    "FUN3D": {0.0: (0.0, 0.00808), 10.0: (1.0840, 0.01253), 15.0: (1.5109, 0.02275)},
    "NTS": {0.0: (0.0, 0.00809), 10.0: (1.0765, 0.01251), 15.0: (1.5100, 0.02187)},
}
# Ladson (NASA TM 4074, 1988), Re 6e6, M 0.15, tripped, via TMR's NACA0012_validation/CLCD_Ladson_expdata.dat:
# (alpha, CL, CD) of the three grit sizes nearest to 0, 10 and 15 deg.
LADSON = {
    "80 grit": [(-0.05, -0.0126, 0.00809), (10.12, 1.0707, 0.01201), (15.26, 1.5129, 0.01900)],
    "120 grit": [(-0.01, -0.0120, 0.00811), (0.01, -0.0122, 0.00804), (10.10, 1.0775, 0.01175), (15.27, 1.5280, 0.01790)],
    "180 grit": [(-0.03, -0.0115, 0.00803), (0.04, -0.0013, 0.00811), (10.18, 1.0809, 0.01165), (15.24, 1.5169, 0.01870)],
}

CHORD = 1.0
SPEED = 90.0  # m/s; with nu 1.5e-5 m2/s: Re = 6e6 per chord
NU = 1.5e-5
# TMR's SST inflow (CFL3D, FUN3D: "freestream turbulence intensity=0.052%", "turbulent viscosity (relative to
# laminar)=0.009"; CFL3D's file header k / a^2 = 9e-9 at M 0.15 gives the same 0.0516 %)
TURBULENCE_INTENSITY = 0.00052
VISCOSITY_RATIO = 0.009
CENTRE = (0.25 * CHORD, 0.0, 0.0)  # the quarter chord: rotation centre and moment reference
DOMAIN_RADIUS = 100.0  # chords (L = the chord): 200 chords across
DOMAIN_WAKE = 100.0
FINE_BASE = 1.0  # m: the fine level's background cell
SURFACE_LEVEL = 10  # the fine surface cell 1/1024 m = 0.977 mm = 110 first layers (D-122)
ANGLES = (0.0, 10.0, 15.0)
STUDY_ANGLE = 10.0
ITERATION_LIMIT = 8000

# Owner rule A6: PASS CL within 3 % and CD within 10 %; PASS WITH NOTE CL 3-5 % or CD 10-20 %; FAIL beyond; at
# 0 deg CL is compared absolutely (the reference is about 0; |CL| < 0.03 x the 10 deg CL counts as within 3 %).
CL_PASS, CL_NOTE, CD_PASS, CD_NOTE = 0.03, 0.05, 0.10, 0.20
# A level whose layers collapsed (first-cell y+ more than 2 x the target over more than 10 % of the wall) does
# not count (A6).
COLLAPSE_SHARE = 0.10


def reference(alpha: float) -> tuple[float, float]:
    """(CL, CD): the mean of the three TMR SST codes at ``alpha``."""
    rows = [TMR_SST[code][alpha] for code in TMR_SST]
    return sum(r[0] for r in rows) / len(rows), sum(r[1] for r in rows) / len(rows)


def verdict(alpha: float, cl: float, cd: float) -> tuple[str, float, float]:
    """(verdict, CL error, CD error): the errors relative to the TMR SST mean (CL at 0 deg: relative to the
    10 deg CL, since the reference is 0)."""
    ref_cl, ref_cd = reference(alpha)
    cl_err = (cl - ref_cl) / (ref_cl if abs(ref_cl) > 1e-6 else reference(10.0)[0])
    cd_err = (cd - ref_cd) / ref_cd
    a, b = abs(cl_err), abs(cd_err)
    if a <= CL_PASS and b <= CD_PASS:
        return "PASS", cl_err, cd_err
    if a <= CL_NOTE and b <= CD_NOTE:
        return "PASS WITH NOTE", cl_err, cd_err
    return "FAIL", cl_err, cd_err


def collapsed(share_over_2x: float | None) -> bool:
    return share_over_2x is not None and share_over_2x > COLLAPSE_SHARE


def stopping():
    """The app's criteria (residuals plus asymptotic, D-058), all of them: the default residual targets and Cl,
    Cd asymptotic over 200 iterations within 0.1 % (Cl) and 0.2 % (Cd), not before iteration 500."""
    from vortexcfd.core.model import AsymptoticCriterion, StoppingCriteria, default_criteria

    return StoppingCriteria(criteria=[*default_criteria(),
                                      AsymptoticCriterion(quantity="Cl", window=200, tolerance=1e-3),
                                      AsymptoticCriterion(quantity="Cd", window=200, tolerance=2e-3)],
                            combine="all", min_iterations=500)


def build_project(folder: Path, alpha: float = STUDY_ANGLE, base_size: float = FINE_BASE, cores: int = 8):
    """The project in ``folder`` (created): the "2D airfoil" preset, the TMR airfoil imported from its Selig file,
    the flow, the domain, the fine level's mesh settings and the stopping criteria. Returns the Project."""
    from vortexcfd.core.presets import BUILTIN_PRESETS, apply_preset
    from vortexcfd.core.project import Project
    from vortexcfd.workflow import part_ops

    folder = Path(folder)
    (folder / "geometry").mkdir(parents=True, exist_ok=True)
    project = Project.new("naca0012")
    project._sim = apply_preset(project.sim, next(p for p in BUILTIN_PRESETS if p.name == "2D airfoil"))
    project.update_physics(nu=NU)
    project.update_inflow(speed=SPEED, alpha_deg=alpha, turbulence_intensity=TURBULENCE_INTENSITY,
                          viscosity_ratio=VISCOSITY_RATIO)
    project.update_reports(reference_length=CHORD, center_of_rotation=CENTRE)
    project.update_domain(radius=DOMAIN_RADIUS, downstream=DOMAIN_WAKE)
    project.update_mesh(base_size=base_size, surface_level_max=SURFACE_LEVEL, surface_level_min=SURFACE_LEVEL - 1)
    project.update_solver(iterations=ITERATION_LIMIT, write_interval=ITERATION_LIMIT, cores=cores,
                          stopping=stopping().model_dump())
    project.update_study("mesh", quantities=["Cl", "Cd", "CmPitch", "Cd_pressure", "Cd_viscous"], cores=cores)
    project.save(folder / "naca0012.json")
    dat = write_dat(folder / "naca0012_tmr.dat")
    project.add_part(part_ops.airfoil_part(folder, dat, "naca0012", set()))
    project.save()
    return project
